tasks.setup:
// First-load trace budgets (ms), mid-range phone on 4G, from the lesson.
// TTFB network-served ~300, HTML parse ~50, CSS/CSSOM ~80, V8 parse+compile ~150,
// first paint ~120, hydration long task ~600 (300ms-1s+ range, take 600),
// interaction ~80, second navigation excluded (it is the repeat load).
const layers = [
  { name: 'network', ms: 300 },
  { name: 'html-parse', ms: 50 },
  { name: 'css', ms: 80 },
  { name: 'v8', ms: 150 },
  { name: 'first-paint', ms: 120 },
  { name: 'hydration', ms: 600 },
  { name: 'interaction', ms: 80 }
];

tasks.starter:
// Trace summary:
// LCP fires at 1.5 s (good). A 900 ms main-thread long task starts at 1.6 s.
// User taps 'Add to cart' at 2.0 s -> INP 700 ms. Network track is idle during the long task.
// Which of the eight layers is the bottleneck, and what change fixes it?

function timeToInteractive(layers) {
  let worst = 0;
  for (const layer of layers) {
    if (layer.ms > worst) worst = layer.ms;
  }
  return worst;
}

